export function setupGracefulShutdown(server, dbPool, timeoutMs = 15000) {
  const connections = new Set();
  server.on('connection', (sock) => {
    connections.add(sock);
    sock.on('close', () => connections.delete(sock));
  });

  const shutdown = async () => {
    // Safety watchdog
    const forceTimer = setTimeout(() => process.exit(1), timeoutMs);
    forceTimer.unref();

    server.close(); // Stop accepting new requests
    for (const sock of connections) sock.destroy(); // Destroy idle sockets
    if (dbPool) await dbPool.end(); // Drain DB pool
    process.exit(0);
  };

  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}

