// Redis Sliding Window Rate Limiter concept:
async function checkRateLimit(redis, clientIp, limit = 100, windowSeconds = 60) {
  const now = Date.now();
  const windowStart = now - (windowSeconds * 1000);
  const key = `rate:${clientIp}`;

  const tx = redis.multi();
  tx.zremrangebyscore(key, 0, windowStart); // Evict requests outside window
  tx.zadd(key, now, now);                   // Record current request
  tx.zcard(key);                            // Count requests in window
  tx.expire(key, windowSeconds);
  const [, , count] = await tx.exec();

  return count <= limit; // True if allowed, False if exceeded (HTTP 429)
}

